vec4 Effect(vec2 uv) {
// Rotate coordinates based on time for animation
vec2 rotated = uv * mat2(cos(iTime), -sin(iTime), sin(iTime), cos(iTime));

// Create color waves with different phases
float r = 0.5 + 0.5 * sin(rotated.x * 10.0 + iTime);
float g = 0.5 + 0.5 * sin(rotated.y * 10.0 + iTime * 0.9);
float b = 0.5 + 0.5 * cos((rotated.x + rotated.y) * 8.0 - iTime);

// Add radial component for depth
float dist = length(uv);
vec3 color = vec3(r, g, b) * sin(dist * 8.0 + iTime) * 0.5 + 0.5;

return vec4(color, 1.0);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = Effect(uv).rgb;//0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Output to screen
    fragColor = vec4(col,1.0);
}
